import React from "react";
import { Cog6ToothIcon, HomeIcon, FlagIcon, ChartBarIcon } from "@heroicons/react/24/outline";

const Sidebar = () => (
  <aside className="w-20 bg-white h-full flex flex-col items-center py-6 shadow-md">
    <div className="mb-8">
      <HomeIcon className="h-7 w-7 text-primary mb-6 cursor-pointer" />
      <FlagIcon className="h-7 w-7 text-gray-400 mb-6 cursor-pointer" />
      <ChartBarIcon className="h-7 w-7 text-gray-400 cursor-pointer" />
    </div>
  </aside>
);

const Topbar = () => (
  <header className="flex items-center justify-between px-8 py-4 bg-white shadow-sm">
    <h1 className="text-2xl font-bold tracking-tight text-primary">Proxima</h1>
    <Cog6ToothIcon className="h-7 w-7 text-gray-400 cursor-pointer" />
  </header>
);

const Layout = ({ children, onShowGoalForm, income, setIncome }) => (
  <div className="flex h-screen bg-background">
    <Sidebar />
    <div className="flex-1 flex flex-col">
      <Topbar />
      <main className="flex-1 p-8 overflow-y-auto">{children}</main>
    </div>
  </div>
);

export default Layout;
